int maxflow(int n, int s, int t, vector<vector<int>> cap) {
    int total = 0;
    while (true) {
        vector<int> parent(n, -1); parent[s] = s;
        queue<int> q; q.push(s);
        while (!q.empty()) {                 // BFS for a shortest augmenting path
            int u = q.front(); q.pop();
            for (int v = 0; v < n; v++)
                if (parent[v] == -1 && cap[u][v] > 0) { parent[v] = u; q.push(v); }
        }
        if (parent[t] == -1) break;           // no augmenting path left
        int bottleneck = INT_MAX;
        for (int v = t; v != s; v = parent[v])
            bottleneck = min(bottleneck, cap[parent[v]][v]);
        for (int v = t; v != s; v = parent[v]) {
            cap[parent[v]][v] -= bottleneck;  // use forward capacity
            cap[v][parent[v]] += bottleneck;  // add backward capacity
        }
        total += bottleneck;
    }
    return total;
}

