int maxflow(int n, int s, int t, int[][] cap) {
    int total = 0;
    while (true) {
        int[] parent = new int[n];
        Arrays.fill(parent, -1); parent[s] = s;
        Queue<Integer> q = new LinkedList<>(); q.add(s);
        while (!q.isEmpty()) {             // BFS for a shortest augmenting path
            int u = q.poll();
            for (int v = 0; v < n; v++)
                if (parent[v] == -1 && cap[u][v] > 0) { parent[v] = u; q.add(v); }
        }
        if (parent[t] == -1) break;        // no augmenting path left
        int bottleneck = Integer.MAX_VALUE;
