function maxflow(n, s, t, cap) {         // cap is an n x n capacity matrix
  let total = 0;
  while (true) {
    const parent = new Array(n).fill(-1); parent[s] = s;
    const q = [s];
    while (q.length) {                    // BFS for a shortest augmenting path
      const u = q.shift();
      for (let v = 0; v < n; v++)
        if (parent[v] === -1 && cap[u][v] > 0) { parent[v] = u; q.push(v); }
    }
    if (parent[t] === -1) break;           // no augmenting path left
    let bottleneck = Infinity;
    for (let v = t; v !== s; v = parent[v]) bottleneck = Math.min(bottleneck, cap[parent[v]][v]);
    for (let v = t; v !== s; v = parent[v]) {
      cap[parent[v]][v] -= bottleneck;     // forward
      cap[v][parent[v]] += bottleneck;     // backward
    }
    total += bottleneck;
  }
  return total;
}
